#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    vector<int> adj(n, 0);
    for (int i = 0; i < m; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        x--; y--;
        adj[x] |= (1 << y);
        adj[y] |= (1 << x);
    }

    int total = 1 << n;
    vector<int> g(total, 0);
    // g[mask] = OR dos conjuntos de conflitos de todos os vértices em mask
    for (int mask = 1; mask < total; mask++) {
        int low = mask & (-mask);
        int v = __builtin_ctz(low);
        g[mask] = g[mask ^ low] | adj[v];
    }

    long long count = 0;
    for (int mask = 1; mask < total; mask++) {
        if ((g[mask] & mask) == 0) count++;
    }

    printf("%lld\n", count);
    return 0;
}
